 vaVars.user_badge_count = 0;
 var identityId = vaInputs.user_sys_id; 
 var badgeAction = "replace" //

 var badgeArray = [];
 var badgeGr = new GlideRecordSecure('x_aleen_snguardian_identity_asset'); 
 badgeGr.addQuery('identity', identityId);
 badgeGr.addNotNullQuery('status');
 badgeGr.addQuery('status.code', 'ACTIVE');
 badgeGr.addQuery('is_deleted',false);
 badgeGr.query();
 while (badgeGr.next()) {
 badgeArray.push({
 'name': badgeGr.getDisplayValue("asset.serial"),
 'value':badgeGr.getValue("sys_id"),
 'description':badgeGr.getDisplayValue("asset.type"),
 'body':'x_aleen_snguardian.asset.jpg'
 });
 }
 vaVars.user_badges_list = JSON.stringify(badgeArray);
 if(badgeArray.length >0){
 vaVars.user_badge_count = badgeArray.length;
 }
})();","id":"f1762558ad1c41c8992f1f3fa36e8afa","name":"Get User Active Badges","goal_id":"primary","applicability":{"type":"Applicability","mode":"script","value":"true"},"expert_mode":false},{"type":"Decision","name":"Active Badges Found?","branches":[{"type":"Branch","label":"Found","expression":{"type":"Applicability","mode":"script","value":"(function() { return (function execute() {
