        "6dfd0a6bd26e42a181b2130d98602426": {
          "id": "6dfd0a6bd26e42a181b2130d98602426",
          "stepType": "AiDataCollector",
          "name": "Data Required Based on Config",
          "purpose": {
            "value": "",
            "mode": "simple"
          },
          "instructions": {
            "value": "",
            "mode": "simple"
          },
          "inputs": [
            {
              "itemId": "3bafb0e173534e6d8cb60a649490f9c3",
              "displayName": "Select new badge",
              "name": "select_new_badge",
              "description": "ask user to select the badge from the given options",
              "discoverable": true,
              "dynamicDescription": {
                "value": "",
                "mode": "simple"
              },
              "type": "carousel-image",
              "variableId": "40a92a2d57874438a664092c077ee863",
              "choices": [
                {
                  "label": "",
                  "value": ""
                },
                {
                  "label": "",
                  "value": ""
                }
              ],
              "mode": "",
              "script": "(function execute() {\n    var options = [];\n    var badgeGr = new GlideRecordSecure('x_aleen_snguardian_asset');\n    badgeGr.addQuery('status.code','UNASSIGNED');\n    badgeGr.addQuery('type.code',vaVars.badge_type);\n    badgeGr.addQuery('system',vaVars.badge_system);\n    badgeGr.query();\n    var count=0;\n    while(badgeGr.next()){\n       if(count<5){\n            options.push({\n            'name': badgeGr.serial,\n            'value':badgeGr.getUniqueValue(),\n            'description':badgeGr.type.code,\n            'body':'x_aleen_snguardian.asset.jpg'\n            })\n       }\n       count++;  //Displaying 5 badges only\n    }\n    return options;\n})()\n",
              "condition": {
                "value": "",
                "mode": "glide_query"
              },
              "stepType": "CarouselPrompt",
              "enforcePrompt": false,
              "helpText": false,
